import{_ as a,o as i,c as e,a3 as t}from"./chunks/framework.6_aCw6yF.js";const c=JSON.parse('{"title":"JetBrains 全家桶一键激活脚本备忘","description":"一条命令搞定 IDEA、PyCharm、GoLand 等全家桶激活，覆盖 Windows / Linux / macOS 三系统，顺手记下实现要点与踩坑。","frontmatter":{"title":"JetBrains 全家桶一键激活脚本备忘","description":"一条命令搞定 IDEA、PyCharm、GoLand 等全家桶激活，覆盖 Windows / Linux / macOS 三系统，顺手记下实现要点与踩坑。","date":"2026-11-19T00:00:00.000Z","category":"工善利器","subCategory":"开发工具","tags":["JetBrains","工具","脚本"],"author":"闲生"},"headers":[],"relativePath":"posts/tools/dev/jetbrains-activation.md","filePath":"posts/tools/dev/jetbrains-activation.md"}'),n={name:"posts/tools/dev/jetbrains-activation.md"};function l(p,s,h,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="jetbrains-全家桶一键激活脚本备忘" tabindex="-1">JetBrains 全家桶一键激活脚本备忘 <a class="header-anchor" href="#jetbrains-全家桶一键激活脚本备忘" aria-label="Permalink to &quot;JetBrains 全家桶一键激活脚本备忘&quot;">​</a></h1><p>社区里一直流传着一套自动化激活脚本，把原本「下载补丁、改配置、填激活码」的流程压成了一行命令。下面把要点整理成备忘，方便换机器时直接翻出来用。</p><h2 id="一、它做了什么" tabindex="-1">一、它做了什么 <a class="header-anchor" href="#一、它做了什么" aria-label="Permalink to &quot;一、它做了什么&quot;">​</a></h2><ul><li>一套脚本适配 <strong>Windows / Linux / macOS</strong> 三大系统；</li><li>覆盖 IDEA、PyCharm、GoLand、WebStorm 等全系列 IDE；</li><li>默认把授权有效期写到一个很远的日期（2099-12-31），也支持自定义授权名与日期；</li><li>全程无需手动下载文件、手动改配置文件。</li></ul><h2 id="二、三系统执行命令" tabindex="-1">二、三系统执行命令 <a class="header-anchor" href="#二、三系统执行命令" aria-label="Permalink to &quot;二、三系统执行命令&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>以<strong>管理员身份</strong>打开 PowerShell（<code>Win + X</code> → Windows PowerShell（管理员）），然后复制执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">irm ckey.run </span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">|</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> iex</span></span></code></pre></div><p>查看调试日志：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">irm ckey.run</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">/</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">debug </span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">|</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> iex</span></span></code></pre></div><p>先看脚本源码再决定是否执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">irm ckey.run</span></span></code></pre></div><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">wget</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --no-check-certificate</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -O</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> bash</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span></span></code></pre></div><p>调试模式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">wget</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --no-check-certificate</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run/debug</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -O</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> bash</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>macOS 默认没有 wget，用 curl；若已安装 wget 可直接套用 Linux 命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">curl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -L</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> bash</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span></span></code></pre></div><p>调试模式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">curl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -L</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run/debug</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> bash</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ckey.run</span></span></code></pre></div><h2 id="三、自定义授权信息" tabindex="-1">三、自定义授权信息 <a class="header-anchor" href="#三、自定义授权信息" aria-label="Permalink to &quot;三、自定义授权信息&quot;">​</a></h2><p>脚本运行后会提示输入两项内容，直接回车则使用默认值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>自定义授权名称(回车默认ckey.run):</span></span>
<span class="line"><span>自定义授权日期(回车默认2099-12-31, 格式 yyyy-MM-dd):</span></span></code></pre></div><p>激活完成后，IDE 的授权信息大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>License: IntelliJ IDEA Active until December 31, 2099</span></span>
<span class="line"><span>Licensed to: JetBrains / ckey.run</span></span>
<span class="line"><span>License ID: 792D98F6C2</span></span></code></pre></div><h2 id="四、执行过程与常见问题" tabindex="-1">四、执行过程与常见问题 <a class="header-anchor" href="#四、执行过程与常见问题" aria-label="Permalink to &quot;四、执行过程与常见问题&quot;">​</a></h2><ol><li><p><strong>先关 IDE</strong>：激活前关闭所有 JetBrains 软件，避免文件占用冲突；</p></li><li><p><strong>执行顺序</strong>：脚本会逐个产品处理，日志形如</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] 处理: IntelliJ IDEA 2025.1</span></span>
<span class="line"><span>[SUCCESS] IntelliJ IDEA 2025.1 激活成功!</span></span>
<span class="line"><span>[SUCCESS] PyCharm 2025.1 激活成功!</span></span></code></pre></div></li><li><p><strong>Mac 激活失败</strong>：如果之前用过别的激活工具，先清掉旧缓存，例如 <code>~/Library/Application Support/JetBrains</code>；</p></li><li><p><strong>路径限制</strong>：目前对非默认安装路径的支持有限，装在自定义目录的 IDE 可能识别不到；</p></li><li><p><strong>安全习惯</strong>：这类脚本的原理是远程拉取并执行，执行前至少先 <code>irm ckey.run</code> / 下载后阅读一遍源码，确认没有多余操作。</p></li></ol><h2 id="五、写在最后" tabindex="-1">五、写在最后 <a class="header-anchor" href="#五、写在最后" aria-label="Permalink to &quot;五、写在最后&quot;">​</a></h2><p>这套脚本本质上是把社区积累的激活流程自动化，仅供学习交流。长期使用还是建议走 JetBrains 官方渠道购买授权，尤其是公司项目；正版授权也能换来稳定的更新和支持。</p>`,30)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
